    """quota.md: the old "archived" (backups kept) is now "saved"; tenants the portal deleted are "archived".
    The corp stage is gone (the type says corporate): corp → client. A POC gets its review date (a month after
    creation)."""
    from datetime import timedelta
    Tenant = apps.get_model("tenants", "Tenant")
    Tenant.objects.filter(status="archived").update(status="saved")
    Tenant.objects.filter(status="deleted").update(status="archived")
    Tenant.objects.filter(stage="corp").update(stage="client")
    for t in Tenant.objects.filter(stage="poc", date_review__isnull=True, status="ok"):
        t.date_review = (t.created_at.date() if t.created_at else None) and t.created_at.date() + timedelta(days=30)
        t.save(update_fields=["date_review"])


